    "BACK THREE":{"ms":"PERTAHANAN TIGA","ja":"3バック","ar":"خط دفاع من ثلاثة","zh-CN":"三后卫","fr":"DÉFENSE À TROIS","de":"DREIERKETTE","ko":"3백","pt":"LINHA DE TRÊS DEFENSORES","ru":"ТРИ ЗАЩИТНИКА","es":"DEFENSA DE TRES"},
