    "DRAFT // BID // BUILD YOUR XI":{"ms":"DRAF // BIDA // BINA XI ANDA","ja":"ドラフト // 入札 // XI編成","ar":"اختيار اللاعبين // المزايدة // تشكيل XI الخاص بك","zh-CN":"选人 // 出价 // 组建你的首发 XI","fr":"DRAFTER // ENCHÉRIR // CRÉER VOTRE XI","de":"DRAFTEN // BIETEN // DEINE XI AUFSTELLEN","ko":"선발 // 입찰 // 내 XI 구성","pt":"SELECIONAR // DAR LANCES // MONTAR SEU XI","ru":"ДРАФТ // СТАВКИ // СВОЯ XI","es":"SELECCIONAR // PUJAR // CREAR TU XI"},
