    "NEW GENERATION XI":{"ms":"NEW GENERATION XI","ja":"新世代世界11傑","ar":"الجيل الجديد XI","zh-CN":"新一代 XI","fr":"La nouvelle génération XI","de":"Eine neue Generation XI","ko":"새로운 세대 XI","pt":"Nova Geração XI","ru":"Новое поколение XI","es":"Nueva generación XI"},
    "NEW INTERNATIONAL PLAYERS":{"ms":"PEMAIN ANTARABANGSA BAHARU","ja":"新規の国際選手","ar":"اللاعبين الدوليين الجدد","zh-CN":"新的国际玩家","fr":"Nouveaux joueurs internationaux","de":"Neue internationale Spieler","ko":"새로운 국제 선수들","pt":"Novos jogadores internacionais","ru":"Новые международные игроки","es":"Nuevos jugadores internacionales"},
