    "PAIR SCORE VS TEAM CONTEXT":{"ms":"SKOR PASANGAN VS KONTEKS PASUKAN","ja":"ペア評価とチーム文脈","ar":"تقييم الزوج مقابل سياق الفريق","zh-CN":"双人默契评分与球队背景","fr":"SCORE DU DUO ET CONTEXTE D’ÉQUIPE","de":"PAARWERT UND TEAMKONTEXT","ko":"두 선수의 점수와 팀 배경","pt":"PONTUAÇÃO DA DUPLA E CONTEXTO DO TIME","ru":"ОЦЕНКА ПАРЫ И КОМАНДНЫЙ КОНТЕКСТ","es":"PUNTUACIÓN DE LA PAREJA Y CONTEXTO DEL EQUIPO"},
    "PAIR SCORES / HISTORY / TIERS":{"ms":"SKOR PASANGAN / SEJARAH / TAHAP","ja":"ペア評価 / 経歴 / 段階","ar":"تقييم الأزواج / المسيرة / المستويات","zh-CN":"双人评分 / 经历 / 等级","fr":"SCORES DES DUOS / PARCOURS / NIVEAUX","de":"PAARWERTE / GESCHICHTE / STUFEN","ko":"선수 조합 점수 / 이력 / 단계","pt":"PONTUAÇÕES DAS DUPLAS / HISTÓRICO / NÍVEIS","ru":"ОЦЕНКИ ПАР / ИСТОРИЯ / УРОВНИ","es":"PUNTUACIONES DE PAREJAS / HISTORIAL / NIVELES"},
    "PASS // WITHDRAW":{"ms":"PASS // TARIK DIRI","ja":"パス // 撤退","ar":"ترك الدور // انسحاب","zh-CN":"放弃加价 // 退出","fr":"PASSER // SE RETIRER","de":"PASSEN // AUSSTEIGEN","ko":"입찰 포기 // 철회","pt":"PASSAR // DESISTIR","ru":"ПАС // ОТКАЗ ОТ СТАВКИ","es":"PASAR // RETIRARSE"},
